def counts26(s):
    counts = [0] * 26
    for ch in s:
        counts[ord(ch) - ord("a")] += 1
    return counts

def can_build(note, magazine):
    counts = counts26(magazine)
    for ch in note:
        i = ord(ch) - ord("a")
        if counts[i] == 0:
            return False            # ran out of this letter
        counts[i] -= 1
    return True

print(can_build("aab", "baa"), can_build("aa", "ab"))  # True False
print(counts26("listen") == counts26("silent"))        # True

