def runs(s):
    out, i = [], 0
    while i < len(s):
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        out.append(s[i] + str(j - i))   # run is s[i:j]
        i = j
    return "".join(out)

print(runs("aabcccccaaa"))      # a2b1c5a3

